module fixed_point_adder(
    parameter Q = 4,
    parameter N = 8,
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    assign c = res;
    always @(*) begin
        if ((a[N-1] == b[N-1])) begin
            // Absolute value addition
            res = a + b;
            res[N-1] = a[N-1];
        end else begin
            // Absolute value subtraction
            if (a > b) begin
                res = a - b;
                res[N-1] = 0;
            end else if (b > a) begin
                res = b - a;
                res[N-1] = ~(|res);
            end
        end
    end

endmodule
